<script setup lang="ts">import { computed } from 'vue';import { useCalendarStore } from '../../stores/calendar.store';const c=useCalendarStore();const months=computed(()=>Array.from({length:12},(_,m)=>new Date(c.cursor.getFullYear(),m,1)));function count(m:Date){return c.events.filter(e=>{const d=new Date(e.start);return d.getFullYear()===m.getFullYear()&&d.getMonth()===m.getMonth()}).length}function open(m:Date){c.cursor=m;c.view='month'}</script><template><div class="year-grid"><button v-for="m in months" :key="m.getMonth()" @click="open(m)"><span>{{m.toLocaleDateString('it-IT',{month:'long'})}}</span><b>{{count(m)}}</b><small>eventi</small></button></div></template><style scoped>.year-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.8rem}.year-grid button{min-height:150px;border:1px solid var(--glass-border);background:rgba(255,255,255,.035);color:inherit;border-radius:18px;padding:1rem;text-align:left;display:grid;align-content:space-between;text-transform:capitalize}.year-grid b{font-size:2rem;color:var(--accent)}.year-grid small{color:var(--text-muted)}@media(max-width:850px){.year-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:600px){.year-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}.year-grid button{min-height:105px}}</style>
